import{_ as e}from"./chunks/more.BA9dr6o4.js";import{_ as o,c as r,o as i,a2 as s}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"Más formas de comparar","description":"Compare imágenes y archivos comprimidos, exporte una comparación como imagen y ajuste la apariencia y el idioma.","frontmatter":{"title":"Más formas de comparar","description":"Compare imágenes y archivos comprimidos, exporte una comparación como imagen y ajuste la apariencia y el idioma."},"headers":[],"relativePath":"es/guide/more.md","filePath":"es/guide/more.md","lastUpdated":1794296122000}'),n={name:"es/guide/more.md"};function t(c,a,d,m,l,p){return i(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="mas-formas-de-comparar" tabindex="-1">Más formas de comparar <a class="header-anchor" href="#mas-formas-de-comparar" aria-label="Permalink to &quot;Más formas de comparar&quot;">​</a></h1><p>El texto es solo una parte de la historia. qDiff abre otros tipos de contenido con la misma idea de comparar uno al lado del otro.</p><img src="'+e+'" alt="Dos imágenes comparadas una al lado de la otra" class="guide-shot"><h2 id="imagenes" tabindex="-1">Imágenes <a class="header-anchor" href="#imagenes" aria-label="Permalink to &quot;Imágenes&quot;">​</a></h2><p>Coloque dos imágenes una junto a otra para compararlas con comodidad, o superpóngalas para ver exactamente dónde difieren, algo muy útil para revisiones de diseño y fotos casi idénticas.</p><h2 id="archivos-comprimidos" tabindex="-1">Archivos comprimidos <a class="header-anchor" href="#archivos-comprimidos" aria-label="Permalink to &quot;Archivos comprimidos&quot;">​</a></h2><p>Un archivo .zip o .tar se puede abrir directamente y comparar como una carpeta. Sin descomprimir y sin archivos temporales que limpiar después.</p><h2 id="archivos-que-no-son-de-texto-plano" tabindex="-1">Archivos que no son de texto plano <a class="header-anchor" href="#archivos-que-no-son-de-texto-plano" aria-label="Permalink to &quot;Archivos que no son de texto plano&quot;">​</a></h2><p>Cuando dos archivos parecen idénticos pero se comportan de forma distinta, qDiff puede compararlos hasta el más mínimo detalle, incluidas diferencias que una vista de texto no puede mostrar.</p><h2 id="guarde-una-comparacion-como-imagen" tabindex="-1">Guarde una comparación como imagen <a class="header-anchor" href="#guarde-una-comparacion-como-imagen" aria-label="Permalink to &quot;Guarde una comparación como imagen&quot;">​</a></h2><p>Seleccione un cambio y expórtelo como una imagen limpia en dos columnas, lista para pegar en un mensaje, un documento o una revisión. La imagen no lleva ninguna marca añadida.</p><h2 id="adaptelo-a-su-gusto" tabindex="-1">Adáptelo a su gusto <a class="header-anchor" href="#adaptelo-a-su-gusto" aria-label="Permalink to &quot;Adáptelo a su gusto&quot;">​</a></h2><ul><li><strong>Apariencia</strong> — clara u oscura, siguiendo a su Mac o ajustada manualmente.</li><li><strong>Idioma</strong> — inglés, chino simplificado, chino tradicional, japonés, alemán, español y francés.</li><li><strong>Fuentes y atajos</strong> — ajuste la comodidad de lectura y use el teclado para las acciones que más repite.</li><li><strong>Comparaciones recientes</strong> — vuelva a abrir desde la pantalla de bienvenida algo que consultó ayer.</li></ul><p>Todo lo anterior está incluido en la versión gratuita.</p><p>¿Tiene alguna duda? <a href="./faq.html">Consulte las preguntas frecuentes</a>.</p>',15)])])}const f=o(n,[["render",t]]);export{g as __pageData,f as default};
